-- SameQ スプリント23（2026-09-23）: お題プールに手書きの英語原文（text_en）を持たせる。
--
-- ## 背景
--
-- お題プール999件（migration 20260908000001）は日本語原文のみで、日本語以外の端末では
-- Apple Translation による端末内機械翻訳で表示していた（spec.md 前提29）。翻訳できないとき
-- （モデル未ダウンロード・非対応の言語ペア・一時的な失敗）は `AppSession.syncPromptTranslation`
-- の `.unavailable` 分岐が日本語原文をそのまま返していた。英語端末の実機検証でこれが露見し、
-- PROGRESS.md に「未決」として残っていた。
--
-- ユーザー決定（2026-09-23）:
--   1. 全言語（英語端末含む）で機械翻訳を優先する。手書きの英語原文は「翻訳できなかった
--      ときの予備」にだけ使う。
--   2. 英訳のついでに、日本語お題の誤字・脱字・不自然な助詞だけを直す（意味・並び順は
--      変えない）。
--
-- ## このマイグレーションの内容
--
--   1. `prompts` に `text_en text null` を追加する。
--   2. `ensure_todays_prompt()` を、ja 配列（誤字修正版）＋ en 配列（新規）で
--      create or replace する。添字アルゴリズムは不変
--      （`((day_index % pool_size) + pool_size/2) % pool_size`）。insert 時に `text_en` も
--      入れる。
--   3. 既存の `prompts` 行のうち「今日以降（`starts_at` が今日の UTC 0:00 以降）」かつ
--      旧 ja 文と一致するものを、新 ja 文 + text_en で更新する（冪等）。過去の
--      `prompts` 行（既にユーザーが見た・回答した記録）は変更しない。
--   4. `official_answers.prompt_text`（20260923000001、日本語文がキー）のうち、
--      上記の ja 誤字修正で文言が変わった5件（「ととしたら」の重複タイプミス4件 +
--      「好きなった」→「好きになった」1件）の
--      キーを新しい ja 文に合わせて更新する（冪等）。`ensure_official_answers()` の
--      カテゴリ前方一致判定（`like '今日%'` 等）は先頭数文字だけを見ており、今回の
--      修正はどれも先頭文字列に触れていないため、フォールバック経路の挙動は変わらない。
--
-- attempt 2（eval-1.md の指摘対応。2026-09-23）:
--   1. 英訳10件の文法崩れ・意味ずれを修正（冠詞 a→an 3件・「about yourself」重複3件・
--      目的語欠落2件・意味ずれ1件・破綻文1件）。
--   2. 「もし一日だけ」146件中「today」を使っていた124件を、パイロットと同じ
--      "for a day" / "for one day" 系の言い回しに書き換え（「一日だけ」＝今日ではなく
--      「一日限定で」の意味を保つ）。
--   3. pos908 / pos963 の ja 修正をコーディネーター指定の文言に変更（下記参照）。
--   4. 全999件を対象に、追加の機械チェック（"a" + 母音始まりの単語、「もし一日だけ」での
--      today 残存、フレーズの繰り返し、重複行）を実行し、いずれも0件であることを確認。
--
-- ## ja の誤字修正一覧（34行。詳細は .product/prompt-pool-v2/pool-final.tsv と
--   .product/sprints/23-prompt-text-en/self-review.md を参照）
--
--   - 24件: 「〜ひとつだけ挙げるととしたら？」の「と」の重複 → 「〜挙げるとしたら？」
--   - pos224: 「好きなった匂い」→「好きになった匂い」（「に」の脱落。48件の legacy プールにも
--             含まれる文言で、official_answers.prompt_text のキーも同時に更新する）
--   - pos7:   「おじいちゃんおばあちゃんなれたら」→「〜になれたら」（「に」の脱落）
--   - pos316: 「有名の人」→「有名な人」（助詞の誤り）
--   - pos318: 「体のどこを止まりたい」→「体のどこで止まりたい」（自動詞「止まる」に
--             「を」は不自然。既存の英訳 "wants to stop and rest" と整合する形に）
--   - pos426: 「振り返えた」→「振り返った」（誤字）
--   - pos617: 「驚きっていますか」→「驚いていますか」（誤字）
--   - pos750: 「好きな同じ」→「好きな同じもの」（名詞の脱落）
--   - pos908: 「すごしてたえた瞬間」→「すごして癒やされた瞬間」（脱字と判断。attempt 1では
--             「癒えた」としたが、evaluator の指摘（eval-1.md）どおり「癒える」は傷に使う語で
--             文脈に合わないため、attempt 2 で「癒やされた」に修正）
--   - pos941: 「一番好きです？」→「一番好きですか？」（終助詞「か」の脱落）
--   - pos963: 「みっつ何を何を買いますか」→「みっつだけ何を買いますか」（語順の乱れ。
--             attempt 2 でコーディネーター指定の文言「そっとみっつだけ買えるとしたら」に変更）
--
--   注: pos474「いま、好きな途をひとつだけ挙げるとしたら？」の「途」は単独では不自然
--   （「途中」等の脱字の可能性がある）が、同じ並びの pos265 が既に「途中」を使っており、
--   「途」→「途中」に直すと ja が重複してしまうため、今回は意図的に直していない
--   （self-review に判断理由を記載）。
--
-- ## 冪等性
--
--   * `alter table ... add column if not exists`。
--   * `ensure_todays_prompt()` は `create or replace function`。
--   * 既存行の backfill・`official_answers` のキー更新はどちらも `where` 条件付きの
--     `update`（対象が既に新しい値なら 0 行が更新されるだけで、再実行しても安全）。
--
-- 本番への `supabase db push` はしない（スプリント22が未評価のため。反映はコーディネーターが
-- 判断する）。
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- 1) prompts.text_en を追加
-- ---------------------------------------------------------------------------
alter table public.prompts add column if not exists text_en text null;

comment on column public.prompts.text_en is
    '手書きの英語原文（あれば）。日本語以外の端末では機械翻訳（Apple Translation）を優先し、
     翻訳が `.unavailable`（モデル未ダウンロード・非対応ペア・一時的な失敗）のときだけ
     これを予備として表示する（スプリント23、AppSession.syncPromptTranslation）。';

-- ---------------------------------------------------------------------------
-- 2) ensure_todays_prompt() を ja 修正版 + en 配列で書き換え
--
-- アルゴリズムは不変。`((day_index % pool_size) + pool_size/2) % pool_size` で
-- 隣接日に近いお題が続けて出ないように中盤から走査する。PromptGenerator.swift /
-- PromptCatalog.swift（candidatePool / candidatePoolEn）と一字一句同期。
-- ---------------------------------------------------------------------------
create or replace function public.ensure_todays_prompt()
returns void
language plpgsql
security definer
set search_path = public
