        'Today, what''s something unexpected you found that made you happy?',
        'This year, what''s a texture you learned about for the first time?',
        'What''s your favorite birdsong right now?',
        'Today, is there something that finished earlier than planned?',
        'If you could get just one thing you love right now, what would it be?',
        'What''s your favorite kind of bustle right now?',
        'If you could take care of someone for a day, what would you do for them?'
    ];
    v_pool_size int := array_length(v_pool_ja, 1);
    v_day_key   text;
    v_day_index int;
    v_start_idx int;
    v_text      text;
    v_text_en   text;
    v_starts_at timestamptz;
    v_ends_at   timestamptz;
    v_truncated_count int;
begin
    v_day_key   := to_char((now() at time zone 'utc')::date, 'YYYYMMDD');
    v_day_index := date(now() at time zone 'utc') - date '1970-01-01';

    -- 隣接日に近いお題が続けて出ないよう中盤から走査。
    v_start_idx := ((v_day_index % v_pool_size) + v_pool_size / 2) % v_pool_size;
    v_text      := v_pool_ja[v_start_idx + 1]; -- Postgres 配列は 1-indexed
    v_text_en   := v_pool_en[v_start_idx + 1];

    v_starts_at := date_trunc('day', now() at time zone 'utc') at time zone 'utc';
    v_ends_at   := v_starts_at + interval '28 hours';

    -- 直前のプロンプトで新プロンプトと重なるものを `ends_at = v_starts_at` に切り詰めて
    -- overlap を消す（`prompts_no_overlap` 制約を満たすため）。
    update public.prompts
    set ends_at = v_starts_at
    where ends_at > v_starts_at
      and starts_at < v_starts_at;
    get diagnostics v_truncated_count = row_count;
    raise notice 'ensure_todays_prompt: truncated % previous prompt(s) to ends_at = %', v_truncated_count, v_starts_at;

    insert into public.prompts (id, text, text_en, starts_at, ends_at)
    values ('prompt_' || v_day_key, v_text, v_text_en, v_starts_at, v_ends_at)
    on conflict (id) do nothing;
end;
$$;

comment on function public.ensure_todays_prompt() is
    '本番 prompts に今日の有効なお題が1件も無いとき、決定的アルゴリズムで
     1件生成してupsertする（冪等）。2026-09-23 スプリント23で候補プール（ja）の
     誤字修正と、手書きの英語原文（en）の追加を行った。Swift 側の
     PromptCatalog.candidatePool / candidatePoolEn と一字一句同期。隣接日に近い
     お題が続けて出ないよう中盤から走査する。';

revoke all on function public.ensure_todays_prompt() from public;
grant execute on function public.ensure_todays_prompt() to authenticated;

