        ('子供の頃、誰の言葉を一番覚えていますか？', '子供の頃、誰の言葉を一番覚えていますか？', 'As a kid, whose words do you remember best?'),
        ('小さい頃、好きな校則のひとことを挙げるとしたら？', '小さい頃、好きな校則のひとことを挙げるとしたら？', 'As a kid, what''s a school rule you actually liked?'),
        ('いま、自分の体のどこを動かしましたか？', 'いま、自分の体のどこを動かしましたか？', 'Just now, what part of your body did you move?'),
        ('今日、自分がまだ知らない自分に会えた瞬間は？', '今日、自分がまだ知らない自分に会えた瞬間は？', 'Today, when did you meet a side of yourself you didn''t know yet?'),
        ('もし一日だけ変えたいことをひとつだけ選ぶとしたら何を変えますか？', 'もし一日だけ変えたいことをひとつだけ選ぶとしたら何を変えますか？', 'If you could change just one thing for a day, what would it be?'),
        ('最近、自分の考えが少し柔らかくなったと感じた瞬間は？', '最近、自分の考えが少し柔らかくなったと感じた瞬間は？', 'Lately, when did you notice your thinking soften a little?'),
        ('この一年で、はじめて気づいた自分の大事にしている人は？', 'この一年で、はじめて気づいた自分の大事にしている人は？', 'This year, what''s a person you discovered means a lot to you?'),
        ('今日、思いがけないものを見つけてちょっとうれしいことは？', '今日、思いがけないものを見つけてちょっとうれしいことは？', 'Today, what''s something unexpected you found that made you happy?'),
        ('この一年で、はじめて知った感触は？', 'この一年で、はじめて知った感触は？', 'This year, what''s a texture you learned about for the first time?'),
        ('いま、好きな鳥の声をひとつだけ挙げるとしたら？', 'いま、好きな鳥の声をひとつだけ挙げるとしたら？', 'What''s your favorite birdsong right now?'),
        ('今日、予定より早く終わったこと、ありますか？', '今日、予定より早く終わったこと、ありますか？', 'Today, is there something that finished earlier than planned?'),
        ('いま、好きなことをひとつだけ手に入れるとしたら？', 'いま、好きなことをひとつだけ手に入れるとしたら？', 'If you could get just one thing you love right now, what would it be?'),
        ('いま、好きなにぎわいをひとつだけ挙げるとしたら？', 'いま、好きなにぎわいをひとつだけ挙げるとしたら？', 'What''s your favorite kind of bustle right now?'),
        ('もし一日だけ誰かの世話をするとしたら何をしますか？', 'もし一日だけ誰かの世話をするとしたら何をしますか？', 'If you could take care of someone for a day, what would you do for them?')
)
update public.prompts p
set text = v.new_ja,
    text_en = v.en
from v
where p.text = v.old_ja
  and p.starts_at >= date_trunc('day', now() at time zone 'utc') at time zone 'utc';

-- ---------------------------------------------------------------------------
-- 4) official_answers.prompt_text のキー更新（誤字修正で文言が変わった5件のみ・冪等）
--
-- 20260923000001 の480行は日本語文をキーにしている。ja 誤字修正でキーの文言が
-- 変わった5件（「〜挙げるととしたら？」→「〜挙げるとしたら？」の「と」重複タイプミス
-- 修正4件 + 「好きなった匂い」→「好きになった匂い」の「に」脱落修正1件）だけキーを
-- 更新する。カテゴリ前方一致判定（`like 'いま%'` / `like '最近%'` 等）は先頭文字列だけを
-- 見ており、この5件はどれも先頭の文言（「いま、好きな」/「最近、好きになった」）のまま
-- 変わらないため、フォールバック経路の挙動には影響しない。
-- ---------------------------------------------------------------------------
update public.official_answers
set prompt_text = case prompt_text
    when 'いま、好きな音をひとつだけ挙げるととしたら？' then 'いま、好きな音をひとつだけ挙げるとしたら？'
    when 'いま、好きな時間をひとつだけ挙げるととしたら？' then 'いま、好きな時間をひとつだけ挙げるとしたら？'
    when 'いま、好きな景色をひとつだけ挙げるととしたら？' then 'いま、好きな景色をひとつだけ挙げるとしたら？'
    when 'いま、好きな季節をひとつだけ挙げるととしたら？' then 'いま、好きな季節をひとつだけ挙げるとしたら？'
    when '最近、好きなった匂いはありますか？' then '最近、好きになった匂いはありますか？'
    else prompt_text
end
where prompt_text in (
    'いま、好きな音をひとつだけ挙げるととしたら？',
    'いま、好きな時間をひとつだけ挙げるととしたら？',
    'いま、好きな景色をひとつだけ挙げるととしたら？',
    'いま、好きな季節をひとつだけ挙げるととしたら？',
    '最近、好きなった匂いはありますか？'
);
